The following Terraform program creates a basic AWS RDS MySQL instance using `io1` provisioned IOPS storage. It includes a dedicated VPC, two private subnets across different Availability Zones, a DB subnet group, and a security group allowing MySQL access within the VPC CIDR.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "db_name" {
  description = "Initial database name."
  type        = string
  default     = "basicdb"
}

variable "db_username" {
  description = "Master username for the RDS instance."
  type        = string
  default     = "adminuser"
}

variable "db_password" {
  description = "Master password for the RDS instance."
  type        = string
  sensitive   = true
  default     = "ChangeMe123456!"
}

variable "vpc_cidr" {
  description = "CIDR block for the RDS VPC."
  type        = string
  default     = "10.0.0.0/16"
}

